/// Community detection by the Louvain method.
///
/// Two phases repeated: move each vertex to whichever neighbouring community
/// most improves modularity, then contract each community to a single vertex
/// and repeat on the smaller graph. The contraction is what lets it find
/// structure at several scales rather than only among immediate neighbours.
///
/// Labels are renumbered from zero in order of first appearance.
///
/// Panics:
/// Panics if the graph is directed.
///
/// Rust: `graph::spectral::community_louvain`
#[pyfunction]
#[pyo3(name = "community_louvain", signature = (g, rng))]
pub fn pyfn_community_louvain(g: crate::generated::types::PyGraph, rng: pyo3::PyRefMut<'_, crate::generated::types::PyRng>) -> PyResult<Vec<usize>> {
    let g = g.inner;
    let mut rng = rng;
    let __r = crate::runtime::guard(|| rust_physics_engine::graph::spectral::community_louvain(&g, &mut rng.inner));
    let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
    Ok(__v)
}

/// Community detection by label propagation.
///
/// Each vertex repeatedly adopts the label carried by the greatest weight
/// among its neighbours, ties broken at random. Near-linear and parameter-
/// free, but the outcome depends on the visiting order, which is why the
/// generator is a parameter rather than fixed.
///
/// Panics:
/// Panics if the graph is directed.
///
/// Rust: `graph::spectral::label_propagation`
#[pyfunction]
#[pyo3(name = "label_propagation", signature = (g, rng))]
pub fn pyfn_label_propagation(g: crate::generated::types::PyGraph, rng: pyo3::PyRefMut<'_, crate::generated::types::PyRng>) -> PyResult<Vec<usize>> {
    let g = g.inner;
    let mut rng = rng;
    let __r = crate::runtime::guard(|| rust_physics_engine::graph::spectral::label_propagation(&g, &mut rng.inner));
    let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
    Ok(__v)
}

